const out = [];
for (const item of $input.all()) {
  const data = item.json;
  const jobs = data.jobs || (Array.isArray(data) ? data : []);
  for (const j of jobs) {
    out.push({
      json: {
        job_title: j.title || '',
        company: j.company_name || '',
        job_url: j.url || '',
        source: 'Remotive',
        location_text: j.candidate_required_location || 'Worldwide',
        salary: j.salary || '',
        description: String(j.description || ''),
        posted_date: j.publication_date || '',
        tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.category || '')
      }
    });
  }
}
return out;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j || !j.title) continue;
  const title = String(j.title);
  const parts = title.split(':');
  const company = parts.length > 1 ? parts[0].trim() : '';
  const jobTitle = parts.length > 1 ? parts.slice(1).join(':').trim() : title;
  out.push({
    json: {
      job_title: jobTitle,
      company,
      job_url: j.link || '',
      source: 'We Work Remotely',
      location_text: 'Remote',
      salary: '',
      description: String(j.contentSnippet || j.content || j.summary || ''),
      posted_date: j.isoDate || j.pubDate || '',
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : ''
    }
  });
}
return out;

// Placeholder normalizer for Wellfound / Himalayas / Dynamite Jobs / YC Work at a Startup / Otta.
// These sources are disabled by default (see Setup Notes). Once you wire in a real
// scraper for one of them, map its output to the standard shape below.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j || (!j.job_title && !j.title && !j.position)) continue;
  out.push({
    json: {
      job_title: j.job_title || j.title || j.position || '',
      company: j.company || '',
      job_url: j.job_url || j.url || j.link || '',
      source: j.source || 'Best-effort source',
      location_text: j.location_text || j.location || 'Unknown',
      salary: j.salary || '',
      description: String(j.description || ''),
      posted_date: j.posted_date || j.date || '',
      tags: j.tags || ''
    }
  });
}
return out;

// Matches the "Search keywords" list from the brief: async/location phrasing OR target role phrasing.
// (Boards here are remote-only by nature, so we don't require the literal word "remote".)
const LOCATION_OR_ASYNC_TERMS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote',
  'work from anywhere', 'anywhere', 'async', 'asynchronous'
];
const ROLE_TERMS = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst',
  'marketing analyst', 'growth analyst', 'ai marketing', 'marketing analytics',
  'automation specialist', 'ai workflow', 'growth marketing', 'martech'
];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!j.job_url || !j.job_title) continue;
  const hay = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  const matched = LOCATION_OR_ASYNC_TERMS.some((t) => hay.includes(t)) || ROLE_TERMS.some((t) => hay.includes(t));
  if (!matched) continue;
  out.push({ json: { ...j, _candidate: true } });
}
return out;

function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (hash << 5) - hash + str.charCodeAt(i);
    hash |= 0;
  }
  return Math.abs(hash).toString(16);
}

const items = $input.all();
const existingUrls = new Set();
const existingKeys = new Set();
const candidates = [];

for (const it of items) {
  const j = it.json;
  if (j._candidate) {
    candidates.push(it);
  } else if (j.job_url) {
    existingUrls.add(String(j.job_url).trim());
    existingKeys.add(`${String(j.company || '').toLowerCase().trim()}|${String(j.job_title || '').toLowerCase().trim()}`);
  }
}

const seenThisRun = new Set();
const unique = [];
const today = new Date().toISOString().slice(0, 10);

for (const it of candidates) {
  const url = String(it.json.job_url || '').trim();
  const key = `${String(it.json.company || '').toLowerCase().trim()}|${String(it.json.job_title || '').toLowerCase().trim()}`;
  if (!url || existingUrls.has(url) || existingKeys.has(key) || seenThisRun.has(url) || seenThisRun.has(key)) continue;
  seenThisRun.add(url);
  seenThisRun.add(key);
  unique.push({ json: { ...it.json, job_id: simpleHash(url || key), date_found: today } });
}

return unique;

const REJECT_PHRASES = {
  us_only: ['us only', 'u.s. only', 'united states only', 'usa only'],
  canada_only: ['canada only'],
  uk_only: ['uk only', 'u.k. only', 'united kingdom only'],
  eu_only: ['eu only', 'e.u. only'],
  europe_only: ['europe only'],
  australia_only: ['australia only'],
  must_be_based_in: ['must be based in', 'must live in', 'must reside in'],
  work_auth: ['must be authorized to work in', 'local work permit required', 'work permit required'],
  hybrid_onsite: ['hybrid', 'onsite', 'on-site', 'office required', 'in-office', 'remote within', 'office-based'],
  fixed_hours: ['fixed us hours', 'fixed eu hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours']
};
const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere', 'apac remote',
  'international contractors', 'contractor role', 'b2b contractor', 'hires via deel',
  'hires via remote.com', 'hires via oyster', 'eor supported', 'remote first', 'distributed team'
];

return $input.all().map((item) => {
  const hay = `${item.json.job_title} ${item.json.description} ${item.json.location_text} ${item.json.tags}`.toLowerCase();
  let matchedReject = null;
  let matchedCategory = null;
  outer:
  for (const [cat, phrases] of Object.entries(REJECT_PHRASES)) {
    for (const p of phrases) {
      if (hay.includes(p)) { matchedReject = p; matchedCategory = cat; break outer; }
    }
  }
  const matchedKeep = KEEP_PHRASES.filter((p) => hay.includes(p));
  const hasReject = !!matchedReject;
  const hasKeep = matchedKeep.length > 0;
  const hardReject = hasReject && !hasKeep;
  return {
    json: {
      ...item.json,
      hard_reject: hardReject,
      hard_filter_ambiguous: hasReject && hasKeep,
      keyword_keep_signal: hasKeep,
      keyword_keep_matches: matchedKeep.join(', '),
      rejection_category: hardReject ? matchedCategory : '',
      rejection_reason: hardReject ? `Matched restrictive phrase: "${matchedReject}"` : ''
    }
  };
});

let parsed = null;
try {
  const resp = $json;
  const text = (resp.content && resp.content[0] && resp.content[0].text) || resp.completion || '';
  const match = String(text).match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : text);
} catch (e) {
  parsed = null;
}

const original = $('Taiwan Hard Filter').item.json;
const safe = parsed || {};
const taiwan_eligible = ['yes', 'no', 'unclear'].includes(safe.taiwan_eligible) ? safe.taiwan_eligible : 'unclear';
const ai_decision = parsed && ['keep', 'reject', 'manual_check'].includes(safe.decision) ? safe.decision : 'manual_check';

return {
  json: {
    ...original,
    taiwan_eligible,
    ai_reason: safe.reason || 'AI response could not be parsed; flagged for manual check.',
    location_risk: ['low', 'medium', 'high'].includes(safe.location_risk) ? safe.location_risk : 'medium',
    timezone_risk: ['low', 'medium', 'high'].includes(safe.timezone_risk) ? safe.timezone_risk : 'medium',
    contractor_possible: safe.contractor_possible || 'unclear',
    ai_decision
  }
};

const REJECT = [
  'strict 9 to 5', 'strict 9-to-5', 'fixed us hours', 'fixed est hours', 'fixed pst hours',
  'fixed cet hours', 'daily live calls required', 'must overlap full business day', 'fixed eu hours'
];
const KEEP = [
  'async', 'asynchronous', 'flexible hours', 'flexible schedule', 'distributed team',
  'remote first', 'low meeting culture', 'work across time zones', 'work across timezones'
];

return $input.all().map((item) => {
  const hay = `${item.json.job_title} ${item.json.description} ${item.json.tags}`.toLowerCase();
  const rejectMatches = REJECT.filter((p) => hay.includes(p));
  const keepMatches = KEEP.filter((p) => hay.includes(p));

  let async_level = 'low';
  if (keepMatches.some((k) => k.includes('async'))) async_level = 'high';
  else if (keepMatches.length > 0) async_level = 'medium';

  const rejectAsync = rejectMatches.length > 0 && keepMatches.length === 0;

  return {
    json: {
      ...item.json,
      async_level,
      async_keep_matches: keepMatches.join(', '),
      async_reject_matches: rejectMatches.join(', '),
      reject_async: rejectAsync,
      rejection_category: rejectAsync ? 'timezone_risk' : (item.json.rejection_category || ''),
      rejection_reason: rejectAsync ? `Requires fixed overlap: "${rejectMatches[0]}"` : (item.json.rejection_reason || '')
    }
  };
});

const PRIMARY = [
  'data analyst', 'data scientist', 'business intelligence', 'bi analyst', 'marketing analyst',
  'performance marketing analyst', 'growth analyst', 'ai marketing', 'ai automation',
  'ai workflow', 'martech', 'automation specialist'
];
const ADJACENT = ['marketing', 'analytics', 'growth', 'data', 'operations', 'consultant', 'strategist'];

return $input.all().map((item) => {
  const hay = `${item.json.job_title} ${item.json.description} ${item.json.tags}`.toLowerCase();
  const primaryMatch = PRIMARY.some((p) => hay.includes(p));
  const adjacentMatch = !primaryMatch && ADJACENT.some((p) => hay.includes(p));
  const role_category = primaryMatch ? 'primary' : (adjacentMatch ? 'adjacent' : 'other');
  const role_fit_points = primaryMatch ? 25 : (adjacentMatch ? 15 : 0);
  return { json: { ...item.json, role_category, role_fit_points } };
});

return $input.all().map((item) => {
  const j = item.json;
  const hay = `${j.job_title} ${j.description} ${j.location_text} ${j.tags}`.toLowerCase();

  const worldwideTerms = [
    'worldwide remote', 'global remote', 'work from anywhere', 'anywhere', 'international contractors',
    'contractor role', 'b2b contractor', 'hires via deel', 'hires via remote.com', 'hires via oyster', 'eor supported'
  ];
  const apacTerms = ['apac remote', 'apac'];
  const strongWorldwide = worldwideTerms.some((t) => hay.includes(t)) || j.contractor_possible === 'yes';
  const apacFriendly = apacTerms.some((t) => hay.includes(t));

  let taiwanPoints = 0;
  if (j.taiwan_eligible === 'no') taiwanPoints = 0;
  else if (strongWorldwide) taiwanPoints = 40;
  else if (apacFriendly) taiwanPoints = 30;
  else if (j.taiwan_eligible === 'unclear' || j.taiwan_eligible === 'yes') taiwanPoints = 20;

  let asyncPoints = 0;
  if (j.async_level === 'high') asyncPoints = 25;
  else if (hay.includes('flexible hours') || hay.includes('flexible schedule')) asyncPoints = 20;
  else if (hay.includes('distributed team')) asyncPoints = 15;
  else if (hay.includes('remote first')) asyncPoints = 10;
  else if (j.async_level === 'medium') asyncPoints = 15;

  const rolePoints = j.role_fit_points || 0;

  const salaryText = `${j.salary || ''} ${j.description || ''}`;
  const nums = (salaryText.match(/\$?\s?(\d{2,3}(?:,\d{3})?|\d{4,6})/g) || [])
    .map((s) => parseInt(s.replace(/[^\d]/g, ''), 10))
    .filter((n) => !isNaN(n) && n > 500);
  let monthlyEstimate = 0;
  if (nums.length) {
    const maxNum = Math.max(...nums);
    monthlyEstimate = maxNum > 20000 ? maxNum / 12 : maxNum;
  }
  let salaryPoints = 0;
  if (monthlyEstimate > 5000) salaryPoints = 25;
  else if (monthlyEstimate > 3000) salaryPoints = 15;
  else if (j.salary) salaryPoints = 10;

  const score = Math.max(0, Math.min(100, taiwanPoints + asyncPoints + rolePoints + salaryPoints));

  return {
    json: {
      ...j,
      score,
      score_breakdown: { taiwanPoints, asyncPoints, rolePoints, salaryPoints, monthlyEstimate }
    }
  };
});

return $input.all().map((item) => {
  const j = item.json;
  const eligible = j.taiwan_eligible;
  const passesOneSentenceRule = !(j.location_risk === 'high' || j.timezone_risk === 'high' || eligible === 'no');

  let application_status = 'shortlisted';
  if (eligible === 'yes' && j.score >= 85 && (j.async_level === 'high' || j.async_level === 'medium') &&
      j.location_risk === 'low' && (j.timezone_risk === 'low' || j.timezone_risk === 'medium')) {
    application_status = 'ready_to_apply';
  } else if (eligible === 'unclear' && j.score >= 85 && j.location_risk === 'medium') {
    application_status = 'manual_check';
  }
  if (!passesOneSentenceRule) application_status = 'rejected';

  const why_good_fit = `${j.role_category === 'primary' ? 'Directly matches target role' : 'Adjacent role fit'}; Taiwan eligibility: ${eligible}; async level: ${j.async_level}; timezone risk: ${j.timezone_risk}.`;

  return {
    json: {
      ...j,
      passes_one_sentence_rule: passesOneSentenceRule,
      application_status,
      why_good_fit,
      rejection_category: !passesOneSentenceRule ? (j.rejection_category || 'one_sentence_rule_fail') : (j.rejection_category || ''),
      rejection_reason: !passesOneSentenceRule ? (j.rejection_reason || 'Fails the one-sentence Taiwan/timezone rule.') : (j.rejection_reason || '')
    }
  };
});

const today = new Date().toISOString().slice(0, 10);
return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      date_rejected: today,
      job_title: j.job_title,
      company: j.company,
      job_url: j.job_url,
      reason: j.rejection_reason || j.ai_reason || 'Did not meet Taiwan eligibility, async, role, or score criteria.',
      rejection_category: j.rejection_category || 'other'
    }
  };
});

let text = '';
try {
  const resp = $json;
  text = (resp.content && resp.content[0] && resp.content[0].text) || '';
} catch (e) {
  text = '';
}
const original = $('IF: Score >= 85 Alert Gate').item.json;
return {
  json: {
    ...original,
    cover_letter_draft: text || '(Cover letter generation failed - draft manually.)'
  }
};

return $input.all().map((item) => {
  const j = item.json;
  const msg = [
    `High-priority Taiwan-eligible async remote job (score ${j.score})`,
    '',
    `${j.job_title} — ${j.company}`,
    `Taiwan eligible: ${j.taiwan_eligible} (${j.ai_reason || ''})`,
    `Async level: ${j.async_level} | Timezone risk: ${j.timezone_risk}`,
    `Salary: ${j.salary || 'Not listed'}`,
    `Apply: ${j.job_url}`,
    '',
    'Cover letter draft:',
    j.cover_letter_draft
  ].join('\n');
  return { json: { ...j, alert_message: msg } };
});

const items = $input.all().map((i) => i.json);
const filtered = items.filter((j) => j.application_status);
const rejected = items.filter((j) => !j.application_status);

const topJobs = filtered
  .filter((j) => j.application_status === 'ready_to_apply' || j.application_status === 'shortlisted')
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 5);

const manualCheck = filtered.filter((j) => j.application_status === 'manual_check');

function bucket(cat) {
  if (cat === 'us_only') return 'us_only';
  if (cat === 'eu_only' || cat === 'europe_only') return 'eu_only';
  if (cat === 'hybrid_onsite') return 'hybrid';
  if (cat === 'timezone_risk') return 'timezone_risk';
  return 'other';
}

const rejectedCounts = { us_only: 0, eu_only: 0, hybrid: 0, timezone_risk: 0, other: 0 };
for (const r of rejected) {
  rejectedCounts[bucket(r.rejection_category)] += 1;
}

return [{
  json: {
    topJobs,
    manualCheck,
    rejectedCounts,
    totalNewJobs: items.length,
    totalReadyToApply: filtered.filter((j) => j.application_status === 'ready_to_apply').length
  }
}];

const d = $input.first().json;
const lines = [];
lines.push('Daily Taiwan Eligible Async Remote Jobs');
lines.push('');
lines.push('Top jobs today:');
lines.push('');

if (!d.topJobs.length) {
  lines.push('(No jobs scored 70+ today.)');
  lines.push('');
}

d.topJobs.forEach((j, idx) => {
  lines.push(`${idx + 1}. ${j.job_title}`);
  lines.push(`Company: ${j.company}`);
  lines.push(`Score: ${j.score}`);
  lines.push(`Taiwan eligible: ${j.taiwan_eligible}`);
  lines.push(`Reason: ${j.ai_reason || ''}`);
  lines.push(`Async level: ${j.async_level}`);
  lines.push(`Timezone risk: ${j.timezone_risk}`);
  lines.push(`Salary: ${j.salary || 'Not listed'}`);
  lines.push(`Why it fits Jerry: ${j.why_good_fit}`);
  lines.push(`Apply link: ${j.job_url}`);
  lines.push('');
});

lines.push('Manual check:');
if (d.manualCheck.length) {
  d.manualCheck.forEach((j) => lines.push(`- ${j.job_title} at ${j.company} (score ${j.score}) — ${j.job_url}`));
} else {
  lines.push('- None today.');
}
lines.push('');

lines.push('Rejected summary:');
lines.push(`Number rejected because of US only: ${d.rejectedCounts.us_only}`);
lines.push(`Number rejected because of EU only: ${d.rejectedCounts.eu_only}`);
lines.push(`Number rejected because of hybrid: ${d.rejectedCounts.hybrid}`);
lines.push(`Number rejected because of timezone risk: ${d.rejectedCounts.timezone_risk}`);

return [{ json: { message: lines.join('\n') } }];
